struct CubeToBeacon {
  uint32_t magic;
  uint8_t  version;
  uint8_t  type;
  uint16_t seq;

  // Only user-facing contract fields:
  uint8_t  maxDistHalfFt;   // 0.5ft units
  uint16_t hold15sUnits;    // 15s units
};

struct BeaconToCube {
  uint32_t magic;
  uint8_t  version;
  uint8_t  type;
  uint16_t seq;

  uint8_t  presence;   // 0/1 (we send "latched presence" = yellow LED state)
  uint8_t  success;    // 0/1 (green LED state)
  uint16_t held15s;    // how many 15s units accumulated (for display)
};

struct BeaconCfgMsg {
  char     magic[4];        // "ROOS"
  uint8_t  version;         // 1
  uint8_t  msgType;         // 1=config
  uint8_t  distHalfFt;      // 1..16 (0.5..8.0 ft)
  uint8_t  timeHalfMin;     // 1..10 (0.5..5.0 min)
  uint32_t seq;             // incrementing
};

struct BeaconAckMsg {
  char     magic[4];        // "ROOS"
  uint8_t  version;         // 1
  uint8_t  msgType;         // 2=ack
  uint32_t seq;             // echoes config seq
  uint8_t  ok;              // 1=accepted, 0=bad
};

struct BeaconPresenceMsg {
  char     magic[4];        // "ROOS"
  uint8_t  version;         // 1
  uint8_t  msgType;         // 3=presence
  uint32_t seq;             // current config seq (or 0 if no session)
  uint8_t  present;         // 0/1 (effective presence for cube)
  uint16_t distCm;          // 0 if unknown
};

